import re

_UNITS = {
    's': 'seconds', 'sec': 'seconds', 'secs': 'seconds',
    'second': 'seconds', 'seconds': 'seconds',
    'm': 'minutes', 'min': 'minutes', 'mins': 'minutes',
    'minute': 'minutes', 'minutes': 'minutes',
    'h': 'hours', 'hr': 'hours', 'hrs': 'hours',
    'hour': 'hours', 'hours': 'hours',
    'd': 'days', 'day': 'days', 'days': 'days',
    'w': 'weeks', 'wk': 'weeks', 'wks': 'weeks',
    'week': 'weeks', 'weeks': 'weeks',
}

_MULTIPLIERS = {
    'seconds': 1,
    'minutes': 60,
    'hours': 3600,
    'days': 86400,
    'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'

_ISO_RE = re.compile(
    r'^P(?:(?P<weeks>' + _NUM + r')W)?'
    r'(?:(?P<days>' + _NUM + r')D)?'
    r'(?:T(?:(?P<hours>' + _NUM + r')H)?'
    r'(?:(?P<minutes>' + _NUM + r')M)?'
    r'(?:(?P<seconds>' + _NUM + r')S)?)?$'
)

_COMPONENT_RE = re.compile(r'\s*(' + _NUM + r')\s*([a-zA-Z]+)')
_COMPONENTS_FULL_RE = re.compile(r'^(?:\s*' + _NUM + r'\s*[a-zA-Z]+)+\s*$')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty duration")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty duration")

    # bare non-negative integer
    if re.fullmatch(r'\d+', stripped):
        return int(stripped)

    # ISO 8601 duration
    if stripped[0] in ('P', 'p'):
        m = _ISO_RE.match(stripped.upper())
        if not m or not any(m.group(g) for g in ('weeks', 'days', 'hours', 'minutes', 'seconds')):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        total = 0.0
        for group, unit in (
            ('weeks', 'weeks'), ('days', 'days'), ('hours', 'hours'),
            ('minutes', 'minutes'), ('seconds', 'seconds'),
        ):
            value = m.group(group)
            if value:
                total += float(value) * _MULTIPLIERS[unit]
        return round(total)

    # clock notation hh:mm:ss or mm:ss
    if ':' in stripped:
        parts = stripped.split(':')
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(re.fullmatch(r'\d+(?:\.\d+)?', p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        values = [float(p) for p in parts]
        if len(values) == 2:
            minutes, seconds = values
            total = minutes * 60 + seconds
        else:
            hours, minutes, seconds = values
            total = hours * 3600 + minutes * 60 + seconds
        return round(total)

    # component based: "1h30m", "1 hour 30 minutes", "3 mins"
    if _COMPONENTS_FULL_RE.fullmatch(stripped):
        total = 0.0
        for num_str, unit_str in _COMPONENT_RE.findall(stripped):
            unit_key = unit_str.lower()
            if unit_key not in _UNITS:
                raise ValueError(f"unknown unit: {unit_str!r}")
            unit = _UNITS[unit_key]
            total += float(num_str) * _MULTIPLIERS[unit]
        return round(total)

    raise ValueError(f"cannot parse duration: {text!r}")

